import 'dart:io';

import 'package:postgresql_parser/postgresql_parser.dart';

/// Refresh quote_identifier's keyword categories from the pinned PG grammars.
void main() {
  final output = StringBuffer(
    '// Generated by tool/generate_psql_keywords.dart from PostgreSQL kwlist.h.\n'
    '// PostgreSQL quotes every keyword except UNRESERVED_KEYWORD.\n'
    '// Do not edit by hand; refresh when adding or updating a grammar.\n\n'
    'final psqlQuotedKeywords = <int, Set<String>>{\n',
  );
  for (final version in PostgresParser.supportedVersions) {
    final file = File.fromUri(
      Platform.script.resolve(
        '../../postgresql_parser/native/pg${version.major}/libpg_query/'
        'src/postgres/include/parser/kwlist.h',
      ),
    );
    final keywords =
        RegExp(r'PG_KEYWORD\("([^"]+)", [^,]+, ([^,]+),')
            .allMatches(file.readAsStringSync())
            .where((match) => match.group(2) != 'UNRESERVED_KEYWORD')
            .map((match) => match.group(1)!)
            .toList()
          ..sort();
    output.writeln('  ${version.major}: (');
    var line = '';
    for (final keyword in keywords) {
      if (line.length + keyword.length > 70) {
        output.writeln("    '$line '");
        line = '';
      }
      line = line.isEmpty ? keyword : '$line $keyword';
    }
    output.writeln("    '$line'\n  ).split(' ').toSet(),");
  }
  output.writeln('};');
  File.fromUri(Platform.script.resolve('../lib/src/psql_keywords.dart'))
      .writeAsStringSync(output.toString());
}
